fn longest_prefix(a: &[i32], b: &[i32]) -> usize {
    // Pair up elements from both slices and count how many
    // initial pairs are equal.
    a.iter()
     .zip(b.iter())
     .take_while(|(x, y)| x == y)
     .count()
}

